                best_score = score
                best_target = p
        if best_target is not None:
            return best_step_toward(best_target)
        return best_step_toward((ox, oy), avoid=(ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best_resource = None
    best_score = None
    for item in resources:
        p = pos(item, None)
        if p is None:
            continue
        score = dist((sx, sy), p)
        if best_score is None or score < best_score:
            best_score = score
            best_resource = p
    if best_resource is not None:
        return best_step_toward(best_resource)

    if env == "resource_collection":
        return best_step_toward((ox, oy), avoid=(ox, oy))

